window.RP_SESSION={"id":"S-e28edb0cc081","messages":[{"id":"RP-0152237","time":"2026-05-06T01:44:00+09:00","room":"RP","name":"아리차","profile":"페트라","identity":"reviewed","type":"dialogue","body":"생각이 많은 밤이다.","characters":["P-0322eff604c2"]},{"id":"RP-0152238","time":"2026-05-06T01:45:00+09:00","room":"RP","name":"아리차","profile":"페트라","identity":"reviewed","type":"dialogue","body":"집착은 어울리지 않는다. 복수? 그것도 솔직히 반쯤은 포기했다고 생각했다.","characters":["P-0322eff604c2"]},{"id":"RP-0152239","time":"2026-05-06T01:46:00+09:00","room":"RP","name":"아리차","profile":"페트라","identity":"reviewed","type":"dialogue","body":"벌써 20년 전의 일.","characters":["P-0322eff604c2"]},{"id":"RP-0152240","time":"2026-05-06T01:46:00+09:00","room":"RP","name":"아리차","profile":"페트라","identity":"reviewed","type":"dialogue","body":"그 빌어먹을 삼촌도 분명, 어디서 뒤통수 맞고 진작에 뒤졌을 거라고 생각했다.","characters":["P-0322eff604c2"]},{"id":"RP-0152241","time":"2026-05-06T01:47:00+09:00","room":"RP","name":"아리차","profile":"페트라","identity":"reviewed","type":"dialogue","body":"칼그람에 몸 담은 것도 녀석을 찾기 위해서였다. 다시 만나자는 약속을 지키고, 녀석의 모가지를 따주기 위해.","characters":["P-0322eff604c2"]},{"id":"RP-0152242","time":"2026-05-06T01:47:00+09:00","room":"RP","name":"아리차","profile":"페트라","identity":"reviewed","type":"dialogue","body":"하지만 막상 그러려고 보니 녀석에 대해 아는 게 너무 없었다.","characters":["P-0322eff604c2"]},{"id":"RP-0152243","time":"2026-05-06T01:48:00+09:00","room":"RP","name":"아리차","profile":"페트라","identity":"reviewed","type":"dialogue","body":"만스라는 이름. 그리고 무장한 데미간 패거리를 몰고 다니는 모습.","characters":["P-0322eff604c2"]},{"id":"RP-0152244","time":"2026-05-06T01:49:00+09:00","room":"RP","name":"아리차","profile":"페트라","identity":"reviewed","type":"dialogue","body":"하지만 칼그람의 불한당 중에서는 녀석의 이름을 아는 자가 없었다. 그래서 죽었다고 생각하기로 했다. 포기라기 보단... 집착을 하지 않는 거라고, 과거를 외면하려 했다.","characters":["P-0322eff604c2"]},{"id":"RP-0152245","time":"2026-05-06T01:50:00+09:00","room":"RP","name":"아리차","profile":"페트라","identity":"reviewed","type":"dialogue","body":"그런 주제에 녀석의 입버릇을 따라하듯, 늘 약속을 들먹이고. 녀석을 따라하기라도 하는 듯 검은색으로 모랫빛 털을 전부 뒤덮었다.","characters":["P-0322eff604c2"]},{"id":"RP-0152246","time":"2026-05-06T01:52:00+09:00","room":"RP","name":"아리차","profile":"페트라","identity":"reviewed","type":"dialogue","body":"이상한 유물이 보여준 20여년 전의 모습은 기억과는 조금 달랐다.","characters":["P-0322eff604c2"]},{"id":"RP-0152247","time":"2026-05-06T01:54:00+09:00","room":"RP","name":"아리차","profile":"페트라","identity":"reviewed","type":"dialogue","body":"만스 삼촌은 아빠에게 화가 나있었다. 그리고 자신의 동료들이 녀석을 막아서자, 오히려 아빠를 책망하며 물러나던 그 모습. 그것을 오해라고 항변하던 아빠...","characters":["P-0322eff604c2"]},{"id":"RP-0152248","time":"2026-05-06T01:54:00+09:00","room":"RP","name":"아리차","profile":"페트라","identity":"reviewed","type":"dialogue","body":"그러고 보면 여지껏 한 번도 왜? 라는 질문을 던져 본 적이 없었다. 그러지 않은 이유는 아마.. 스스로도 잘 알고 있다. 녀석을 미워 할 이유를 잃기 싫었던 거겠지.","characters":["P-0322eff604c2"]},{"id":"RP-0152249","time":"2026-05-06T01:56:00+09:00","room":"RP","name":"아리차","profile":"페트라","identity":"reviewed","type":"dialogue","body":"하지만...","characters":["P-0322eff604c2"]},{"id":"RP-0152250","time":"2026-05-06T01:58:00+09:00","room":"RP","name":"아리차","profile":"페트라","identity":"reviewed","type":"dialogue","body":"녀석의 얼굴을 다시금 보고서 깨달았다. 자신의 본심을.","characters":["P-0322eff604c2"]},{"id":"RP-0152251","time":"2026-05-06T01:59:00+09:00","room":"RP","name":"아리차","profile":"페트라","identity":"reviewed","type":"dialogue","body":"복잡한 사정 따윈 알바 없다. 세상에 사연 없는 녀석이 어디 있을까?","characters":["P-0322eff604c2"]},{"id":"RP-0152252","time":"2026-05-06T02:00:00+09:00","room":"RP","name":"아리차","profile":"페트라","identity":"reviewed","type":"dialogue","body":"그러니 이유가 뭐든...\n메시지가 삭제되었습니다.","characters":["P-0322eff604c2"]},{"id":"RP-0152253","time":"2026-05-06T02:00:00+09:00","room":"RP","name":"아리차","profile":"페트라","identity":"reviewed","type":"dialogue","body":"\"살아있다면 반드시 죽인다.\"\n메시지가 삭제되었습니다.","characters":["P-0322eff604c2"]},{"id":"RP-0152255","time":"2026-05-06T02:04:00+09:00","room":"RP","name":"아리차","profile":"페트라","identity":"reviewed","type":"dialogue","body":"사진","characters":["P-0322eff604c2"]},{"id":"RP-0152256","time":"2026-05-06T02:04:00+09:00","room":"RP","name":"아리차","profile":"페트라","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-0322eff604c2"]},{"id":"RP-0152257","time":"2026-05-06T02:04:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"...다음 시간에.","characters":[]}]};
